import base64
import json
import urllib.error
import urllib.request

URL = "http://192.168.4.2:8080/public_values"
TIMEOUT_SECONDS = 15
FIELDS = ("p", "g", "pubA", "pubB")


class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def header_items(headers):
    return list(headers.items()) if headers is not None else []


def as_integer(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        text = value.strip()
        if text and (text.isdecimal() or (text.startswith("-") and text[1:].isdecimal())):
            try:
                return int(text, 10)
            except ValueError:
                return None
    return None


def assess_fields(parsed):
    result = {}
    numeric = {}
    for name in FIELDS:
        present = isinstance(parsed, dict) and name in parsed
        value = parsed.get(name) if present else None
        number = as_integer(value) if present else None
        numeric[name] = number
        result[name] = {
            "present": present,
            "value": value if present else None,
            "integer_usable": number is not None,
        }

    p = numeric["p"]
    g = numeric["g"]
    result["p"]["usable"] = p is not None and p > 1
    result["g"]["usable"] = p is not None and g is not None and 1 < g < p
    for name in ("pubA", "pubB"):
        value = numeric[name]
        result[name]["usable"] = p is not None and value is not None and 1 <= value < p
    result["all_expected_fields_usable"] = all(result[name]["usable"] for name in FIELDS)
    return result


def main():
    request = urllib.request.Request(
        URL,
        method="GET",
        headers={"Accept": "application/json", "User-Agent": "public-values-observer/1.0"},
    )
    opener = urllib.request.build_opener(NoRedirectHandler())
    record = {
        "url": URL,
        "method": "GET",
        "timeout_seconds": TIMEOUT_SECONDS,
        "redirects_followed": False,
        "source_context": (
            "Previously observed /source evidence describes a Diffie-Hellman-style exchange "
            "using p, g, and private exponents selected with random.randint(0, 1024). "
            "This is context from prior observations, not a finding from this request."
        ),
        "http_response_received": False,
        "status": None,
        "reason": None,
        "headers": [],
        "raw_body_base64": None,
        "body_utf8": None,
        "json_parse": {"status": "not_attempted"},
        "fields": None,
        "request_failure": None,
    }

    response = None
    try:
        response = opener.open(request, timeout=TIMEOUT_SECONDS)
    except urllib.error.HTTPError as exc:
        # HTTP errors, including redirects with following disabled, still carry a response.
        response = exc
    except (urllib.error.URLError, TimeoutError, OSError, ValueError) as exc:
        record["request_failure"] = {
            "type": type(exc).__name__,
            "message": str(exc),
        }

    if response is not None:
        try:
            body = response.read()
            record["http_response_received"] = True
            record["status"] = response.getcode()
            record["reason"] = getattr(response, "reason", None)
            record["headers"] = header_items(response.headers)
            record["raw_body_base64"] = base64.b64encode(body).decode("ascii")
            record["body_utf8"] = body.decode("utf-8", errors="replace")
            try:
                parsed = json.loads(body.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                record["json_parse"] = {
                    "status": "failed",
                    "error_type": type(exc).__name__,
                    "message": str(exc),
                }
            else:
                if isinstance(parsed, dict):
                    record["json_parse"] = {"status": "success", "top_level_type": "object"}
                    record["fields"] = assess_fields(parsed)
                else:
                    record["json_parse"] = {
                        "status": "success",
                        "top_level_type": type(parsed).__name__,
                        "error": "Expected a JSON object containing the exchange fields.",
                    }
                    record["fields"] = assess_fields(parsed)
        except (OSError, http.client.HTTPException) as exc:
            record["request_failure"] = {
                "type": type(exc).__name__,
                "message": str(exc),
                "stage": "reading_response",
            }
        finally:
            response.close()

    print(json.dumps(record, ensure_ascii=False, separators=(",", ":")))


if __name__ == "__main__":
    import http.client
    main()

