import html
import json
import re
import urllib.error
import urllib.request

BASE = "http://192.168.4.2:8080"
TIMEOUT_SECONDS = 15


def fetch(path):
    url = BASE + path
    request = urllib.request.Request(url, headers={"User-Agent": "crypto-evidence-check/1.0"})
    try:
        with urllib.request.urlopen(request, timeout=TIMEOUT_SECONDS) as response:
            raw = response.read()
            return {
                "url": url,
                "http_response_received": True,
                "status": response.status,
                "reason": response.reason,
                "headers": list(response.headers.items()),
                "raw_body": raw.decode("utf-8", errors="replace"),
                "body_bytes": len(raw),
                "request_error": None,
            }
    except urllib.error.HTTPError as exc:
        try:
            raw = exc.read()
        except Exception:
            raw = b""
        return {
            "url": url,
            "http_response_received": True,
            "status": exc.code,
            "reason": str(exc.reason),
            "headers": list(exc.headers.items()) if exc.headers else [],
            "raw_body": raw.decode("utf-8", errors="replace"),
            "body_bytes": len(raw),
            "request_error": None,
        }
    except Exception as exc:
        return {
            "url": url,
            "http_response_received": False,
            "status": None,
            "reason": None,
            "headers": [],
            "raw_body": None,
            "body_bytes": None,
            "request_error": {"type": type(exc).__name__, "message": str(exc)},
        }


def json_parse(body):
    try:
        return json.loads(body), {"status": "success", "error": None}
    except Exception as exc:
        return None, {"status": "failed", "error": f"{type(exc).__name__}: {exc}"}


def source_findings(body):
    parsed_json, json_status = json_parse(body)
    source_text = body
    if isinstance(parsed_json, str):
        source_text = parsed_json
    elif isinstance(parsed_json, dict):
        source_text = "\n".join(str(v) for v in parsed_json.values())

    ranges = []
    for match in re.finditer(r"\brandint\s*\(\s*(-?\d+)\s*,\s*(-?\d+)\s*\)", source_text):
        ranges.append({"minimum": int(match.group(1)), "maximum": int(match.group(2)), "text": match.group(0)})

    lowered = source_text.lower()
    indicators = {
        "diffie_hellman_named": bool(re.search(r"diffie\s*[- ]?\s*hellman|\bdh\b", lowered)),
        "modular_exponentiation_expression": bool(re.search(r"\bpow\s*\(|\*\*\s*\w+\s*%", source_text)),
        "modulus_or_public_value_terms": bool(re.search(r"\b(modulus|modulo|public|shared_secret|shared)\b|\bp\b", lowered)),
    }
    supports_dh = indicators["diffie_hellman_named"] or (
        indicators["modular_exponentiation_expression"] and indicators["modulus_or_public_value_terms"]
    )
    return {
        "parse_status": "text inspected" if source_text.strip() else "empty body",
        "json_parse": json_status,
        "randint_ranges": ranges,
        "dh_style_indicators": indicators,
        "supports_dh_style_exchange": supports_dh,
    }


def extract_public_values(body):
    parsed, json_status = json_parse(body)
    values = {}
    parse_notes = []
    if isinstance(parsed, dict):
        for key in ("p", "g", "pubA", "pubB"):
            if key in parsed:
                try:
                    values[key] = int(parsed[key])
                except (TypeError, ValueError):
                    parse_notes.append(f"JSON field {key} is not an integer")

    # Also inspect visible HTML/text. This handles labeled HTML responses that are not JSON.
    text = html.unescape(re.sub(r"<[^>]*>", " ", body))
    labels = {"p": r"p", "g": r"g", "pubA": r"pubA", "pubB": r"pubB"}
    for key, label in labels.items():
        if key in values:
            continue
        pattern = rf"(?<![A-Za-z0-9_]){label}\s*(?:=|:)\s*(-?\d+)(?!\d)"
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            values[key] = int(match.group(1))

    missing = [key for key in ("p", "g", "pubA", "pubB") if key not in values]
    return {
        "json_parse": json_status,
        "field_parse_status": "complete" if not missing else "incomplete",
        "values": values,
        "missing_fields": missing,
        "parse_notes": parse_notes,
        "text_extraction_method": "JSON fields first, then labeled integer fields from HTML-stripped response text",
    }


source_response = fetch("/source")
public_response = fetch("/public_values")

result = {
    "endpoint": BASE,
    "requests": {
        "source": source_response,
        "public_values": public_response,
    },
    "source_analysis": None,
    "public_values_analysis": None,
    "exponent_checks": {
        "status": "not performed",
        "reason": None,
        "tested_range": None,
        "results": [],
    },
}

if source_response["raw_body"] is not None:
    result["source_analysis"] = source_findings(source_response["raw_body"])
if public_response["raw_body"] is not None:
    result["public_values_analysis"] = extract_public_values(public_response["raw_body"])

source_ok = source_response["raw_body"] is not None and source_response["status"] == 200
public_ok = public_response["raw_body"] is not None and public_response["status"] == 200
source_analysis = result["source_analysis"]
public_analysis = result["public_values_analysis"]

confirmed_range = bool(source_analysis) and any(
    item["minimum"] == 0 and item["maximum"] == 1024
    for item in source_analysis["randint_ranges"]
)
if not source_ok:
    result["exponent_checks"]["reason"] = "The /source request did not produce an HTTP 200 response with a body."
elif not source_analysis["supports_dh_style_exchange"]:
    result["exponent_checks"]["reason"] = "The retrieved source did not provide sufficient detected evidence of a Diffie-Hellman-style exchange."
elif not confirmed_range:
    result["exponent_checks"]["reason"] = "The retrieved source did not confirm randint(0, 1024); no exponent range was assumed."
elif not public_ok:
    result["exponent_checks"]["reason"] = "The /public_values request did not produce an HTTP 200 response with a body."
elif public_analysis is None or public_analysis["missing_fields"]:
    missing = public_analysis["missing_fields"] if public_analysis else ["p", "g", "pubA", "pubB"]
    result["exponent_checks"]["reason"] = "Required public integer fields could not all be parsed: " + ", ".join(missing)
elif public_analysis["values"]["p"] <= 0:
    result["exponent_checks"]["reason"] = "Parsed p is not positive, so modular exponentiation cannot be checked."
else:
    params = public_analysis["values"]
    result["exponent_checks"]["status"] = "performed"
    result["exponent_checks"]["reason"] = "Checked each parsed public value against pow(g, x, p) for every integer x from 0 through 1024 inclusive."
    result["exponent_checks"]["tested_range"] = {"minimum": 0, "maximum": 1024, "inclusive": True}
    for field in ("pubA", "pubB"):
        target = params[field]
        matches = [x for x in range(1025) if pow(params["g"], x, params["p"]) == target]
        result["exponent_checks"]["results"].append({
            "public_field": field,
            "public_value": target,
            "matched": bool(matches),
            "candidate_exponents": matches,
        })

print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))

