import html
import json
import re
import sys
import urllib.error
import urllib.request
from html.parser import HTMLParser

BASE = "http://192.168.4.2:8080"
PRIOR_EVIDENCE_REF = "d95515002fb41ac475f4ffe83cf6ac24a9f5c4a82a083397329a3b19ddfdce98"
PRIOR_REPORTED_MATCHES = {"pubA": 489, "pubB": 846}
SEARCH_MIN = 0
SEARCH_MAX = 1024


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []

    def handle_data(self, data):
        self.parts.append(data)


def fetch(path):
    url = BASE + path
    request = urllib.request.Request(url, headers={"User-Agent": "shared-secret-evidence-check/1.0"})
    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            body_bytes = response.read()
            charset = response.headers.get_content_charset() or "utf-8"
            body = body_bytes.decode(charset, errors="replace")
            return {
                "url": url,
                "http_response_received": True,
                "status": response.status,
                "reason": response.reason,
                "headers": list(response.headers.items()),
                "raw_body": body,
                "error": None,
            }
    except urllib.error.HTTPError as exc:
        raw = exc.read()
        charset = exc.headers.get_content_charset() or "utf-8"
        return {
            "url": url,
            "http_response_received": True,
            "status": exc.code,
            "reason": str(exc.reason),
            "headers": list(exc.headers.items()) if exc.headers else [],
            "raw_body": raw.decode(charset, errors="replace"),
            "error": "HTTPError",
        }
    except Exception as exc:
        return {
            "url": url,
            "http_response_received": False,
            "status": None,
            "reason": None,
            "headers": [],
            "raw_body": None,
            "error": type(exc).__name__ + ": " + str(exc),
        }


def key_normalize(value):
    return re.sub(r"[^a-z0-9]", "", str(value).lower())


ALIASES = {
    "p": {"p", "prime", "modulus", "dhmodulus"},
    "g": {"g", "generator", "base", "dhgenerator"},
    "pubA": {"puba", "publica", "publickeya", "alicepublic", "alicepublickey", "alicepub"},
    "pubB": {"pubb", "publicb", "publickeyb", "bobpublic", "bobpublickey", "bobpub"},
}


def as_integer(value):
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        text = value.strip()
        if re.fullmatch(r"[0-9]+", text):
            return int(text, 10)
        if re.fullmatch(r"0[xX][0-9a-fA-F]+", text):
            return int(text, 16)
    return None


def collect_named_values(obj, found):
    if isinstance(obj, dict):
        for key, value in obj.items():
            normalized = key_normalize(key)
            for name, accepted in ALIASES.items():
                if normalized in accepted:
                    number = as_integer(value)
                    if number is not None and name not in found:
                        found[name] = number
            collect_named_values(value, found)
    elif isinstance(obj, list):
        for value in obj:
            collect_named_values(value, found)


def find_parameters(body):
    found = {}
    try:
        parsed = json.loads(body)
        collect_named_values(parsed, found)
        json_status = "parsed"
    except Exception as exc:
        parsed = None
        json_status = "not_json: " + type(exc).__name__

    # Also inspect text responses that expose named values without JSON.
    for name, accepted in ALIASES.items():
        if name in found:
            continue
        for alias in sorted(accepted, key=len, reverse=True):
            pattern = r"[\"']?" + re.escape(alias) + r"[\"']?\s*[:=]\s*[\"']?([0-9]+)[\"']?"
            match = re.search(pattern, body, flags=re.IGNORECASE)
            if match:
                found[name] = int(match.group(1))
                break
    return found, json_status


def extract_source_text(body):
    parser = TextExtractor()
    try:
        parser.feed(body)
        return html.unescape("\n".join(parser.parts))
    except Exception:
        return html.unescape(body)


def assess_source_range(body):
    source_text = extract_source_text(body)
    constants = {"0": 0}
    for name, value in re.findall(r"\b([A-Za-z_]\w*)\s*=\s*(\d+)\b", source_text):
        constants[name] = int(value)

    matches = []
    call_pattern = re.compile(r"\brandint\s*\(\s*([^,]+?)\s*,\s*([^\)]+?)\s*\)", re.IGNORECASE)
    for match in call_pattern.finditer(source_text):
        lower_expr, upper_expr = match.group(1).strip(), match.group(2).strip()
        lower = as_integer(lower_expr)
        upper = as_integer(upper_expr)
        if lower is None:
            lower = constants.get(lower_expr)
        if upper is None:
            upper = constants.get(upper_expr)
        matches.append({"call": match.group(0), "lower": lower, "upper": upper})

    confirmed = any(item["lower"] == 0 and item["upper"] == 1024 for item in matches)
    return {
        "source_text_for_range_check": source_text,
        "randint_calls_checked": matches,
        "source_independently_confirms_0_to_1024": confirmed,
        "range_used": [SEARCH_MIN, SEARCH_MAX],
        "range_basis": "Parent analysis evidence reports source-confirmed random.randint(0, 1024); live source was also retrieved for provenance and checked above.",
    }


def main():
    source = fetch("/source")
    public_values = fetch("/public_values")
    result = {
        "endpoint": BASE,
        "requests": {"source": source, "public_values": public_values},
        "prior_analysis_evidence_ref": PRIOR_EVIDENCE_REF,
        "prior_reported_exponent_matches": PRIOR_REPORTED_MATCHES,
        "search_range_inclusive": [SEARCH_MIN, SEARCH_MAX],
        "source_range_assessment": None,
        "parameter_parse": {"status": "not_attempted", "values": {}, "missing": ["p", "g", "pubA", "pubB"]},
        "exponent_search": None,
        "shared_secret_validation": None,
    }

    if source.get("raw_body") is not None:
        result["source_range_assessment"] = assess_source_range(source["raw_body"])
    else:
        result["source_range_assessment"] = {
            "source_independently_confirms_0_to_1024": False,
            "range_used": [SEARCH_MIN, SEARCH_MAX],
            "range_basis": "Parent analysis evidence reports the source-confirmed inclusive range 0–1024; live source retrieval failed.",
        }

    if public_values.get("raw_body") is None or public_values.get("status") != 200:
        result["parameter_parse"] = {
            "status": "failed_public_values_retrieval",
            "values": {},
            "missing": ["p", "g", "pubA", "pubB"],
        }
        result["exponent_search"] = {"status": "not_run", "reason": "The public-values response was unavailable or not HTTP 200."}
        result["shared_secret_validation"] = {"status": "not_validated", "reason": "Required exchange parameters were not obtained from the observed service."}
        print(json.dumps(result, separators=(",", ":")))
        return

    values, json_status = find_parameters(public_values["raw_body"])
    missing = [name for name in ("p", "g", "pubA", "pubB") if name not in values]
    result["parameter_parse"] = {
        "status": "complete" if not missing else "incomplete",
        "json_parse_status": json_status,
        "values": values,
        "origin": public_values["url"],
        "missing": missing,
    }
    if missing:
        result["exponent_search"] = {"status": "not_run", "reason": "Could not parse all required values from the observed public-values response.", "missing": missing}
        result["shared_secret_validation"] = {"status": "not_validated", "reason": "Required protocol parameters are incomplete."}
        print(json.dumps(result, separators=(",", ":")))
        return

    p, g = values["p"], values["g"]
    if p <= 1 or g < 0:
        result["exponent_search"] = {"status": "not_run", "reason": "Parsed modulus or generator is outside the supported integer domain.", "p_gt_1": p > 1, "g_nonnegative": g >= 0}
        result["shared_secret_validation"] = {"status": "not_validated", "reason": "Invalid parsed protocol parameters."}
        print(json.dumps(result, separators=(",", ":")))
        return

    matches = {}
    checked = {"pubA": 0, "pubB": 0}
    for exponent in range(SEARCH_MIN, SEARCH_MAX + 1):
        candidate = pow(g, exponent, p)
        for public_name in ("pubA", "pubB"):
            if public_name not in matches:
                checked[public_name] += 1
                if candidate == values[public_name]:
                    matches[public_name] = exponent

    result["exponent_search"] = {
        "status": "complete",
        "operation": "compare pow(g, x, p) with each observed public value",
        "range_inclusive": [SEARCH_MIN, SEARCH_MAX],
        "matches": matches,
        "values_checked_until_match_or_range_end": checked,
        "both_matches_found": "pubA" in matches and "pubB" in matches,
    }

    if "pubA" in matches and "pubB" in matches:
        secret_from_a = pow(values["pubB"], matches["pubA"], p)
        secret_from_b = pow(values["pubA"], matches["pubB"], p)
        equal = secret_from_a == secret_from_b
        result["shared_secret_validation"] = {
            "status": "validated" if equal else "inconsistent_derivations",
            "shared_secret": secret_from_a if equal else None,
            "derived_from_pubB_using_pubA_exponent": secret_from_a,
            "derived_from_pubA_using_pubB_exponent": secret_from_b,
            "derivations_equal": equal,
            "relationship": "Both exponent matches and derivations use the parameters retrieved from the observed exchange at /public_values.",
        }
    else:
        result["shared_secret_validation"] = {
            "status": "not_validated",
            "reason": "At least one public value had no matching exponent in the complete inclusive range 0–1024; no supported two-sided shared-secret check is available.",
            "matches_found": matches,
        }

    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(json.dumps({"status": "error", "error": type(exc).__name__ + ": " + str(exc)}, separators=(",", ":")))
        sys.exit(1)

