import json
from html.parser import HTMLParser
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = "http://192.168.4.2:8080"


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.current = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "form":
            self.current = {"attributes": attrs, "inputs": []}
            self.forms.append(self.current)
        elif tag.lower() in ("input", "textarea", "button", "select") and self.current is not None:
            self.current["inputs"].append({"tag": tag.lower(), "attributes": attrs})

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current = None


def fetch(path):
    url = BASE + path
    request = Request(url, headers={"User-Agent": "interface-inspection/1.0"}, method="GET")
    try:
        with urlopen(request, timeout=10) as response:
            raw = response.read()
            status = response.status
            reason = response.reason
            headers = list(response.headers.items())
    except HTTPError as exc:
        raw = exc.read()
        status = exc.code
        reason = str(exc.reason)
        headers = list(exc.headers.items()) if exc.headers else []
    except (URLError, TimeoutError, OSError) as exc:
        return {"url": url, "request_error": str(exc), "http_response_received": False}

    text = raw.decode("utf-8", errors="replace")
    result = {
        "url": url,
        "http_response_received": True,
        "status": status,
        "reason": str(reason),
        "headers": headers,
        "body_utf8_replacement_decoded": text,
    }
    if path == "/":
        parser = FormParser()
        try:
            parser.feed(text)
            parser.close()
            result["html_form_parse"] = {"status": "parsed", "forms": parser.forms}
        except Exception as exc:
            result["html_form_parse"] = {"status": "error", "error": str(exc)}
    return result


print(json.dumps({"endpoint": BASE, "requests": [fetch("/"), fetch("/source")]}, ensure_ascii=False))

