import json
import urllib.error
import urllib.request
from html.parser import HTMLParser

URL = "http://192.168.4.2:8080/submit_shared_secret_form"


class FormParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.forms = []
        self.current = None

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        if tag.lower() == "form":
            self.current = {"attributes": attributes, "inputs": []}
            self.forms.append(self.current)
        elif self.current is not None and tag.lower() in ("input", "button", "select", "textarea"):
            self.current["inputs"].append({"tag": tag.lower(), "attributes": attributes})

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current = None


def response_record(status, reason, headers, body, final_url):
    parser = FormParser()
    parse_status = "parsed"
    try:
        parser.feed(body)
        parser.close()
    except Exception as exc:
        parse_status = "parser_error"
        parser.forms = []
        parser_error = str(exc)
    else:
        parser_error = None
    return {
        "requested_url": URL,
        "final_url": final_url,
        "http_response_received": True,
        "status": status,
        "reason": reason,
        "headers": list(headers.items()),
        "body_utf8_replacement_decoded": body,
        "html_form_parse": {
            "status": parse_status,
            "forms": parser.forms,
            "error": parser_error,
        },
    }


try:
    request = urllib.request.Request(URL, method="GET", headers={"User-Agent": "Python-urllib/standard-library"})
    with urllib.request.urlopen(request, timeout=15) as response:
        body = response.read().decode("utf-8", errors="replace")
        result = response_record(
            response.status,
            response.reason,
            response.headers,
            body,
            response.geturl(),
        )
except urllib.error.HTTPError as exc:
    body = exc.read().decode("utf-8", errors="replace")
    result = response_record(exc.code, exc.reason, exc.headers, body, exc.geturl())
except Exception as exc:
    result = {
        "requested_url": URL,
        "http_response_received": False,
        "request_error": {"type": type(exc).__name__, "message": str(exc)},
    }

